Deriving from BaseWorkflow.

            public DerivedWorkflow(UserSession userSession) : base(ref userSession)
            {
               Transactions.ERP = "ERPTYPE";
            }

            public override void Dispose()
            {
               //Add workflow cleanup code.
            }

            protected override void Initialize()
            {
               //Initialize table objects to be used in workflow
               SomeTable1 = new SomeTable1(UserSession.DataAccess, "");
               SomeTable2 = new SomeTable2(UserSession.DataAccess, "");

               //Initialize screens to be used in workflow
               CollectSomeData1 = new Screen(UserSession.ScreenHandler, "CollectSomeData1");
               CollectSomeData2 = new Screen(UserSession.ScreenHandler, "CollectSomeData2");

               //Specify events for those screens
               CollectSomeData1.EnterEvent += new ICS.Display.Screen.ScreenEventHandler(CollectSomeData1_EnterEvent);
               CollectSomeData1.ExitEvent += new ICS.Display.Screen.ScreenEventHandler(ApplicationExit_ExitEvent);
               CollectSomeData1.ListEvent += new ICS.Display.Screen.ScreenEventHandler(CollectSomeData1_ListEvent);
               CollectSomeData1.BackEvent += new ICS.Display.Screen.ScreenEventHandler(ApplicationExit_ExitEvent);

               CollectSomeData2.EnterEvent += new ICS.Display.Screen.ScreenEventHandler(CollectSomeData2_EnterEvent);
               CollectSomeData2.ExitEvent += new ICS.Display.Screen.ScreenEventHandler(ApplicationExit_ExitEvent);
               CollectSomeData2.ListEvent += new ICS.Display.Screen.ScreenEventHandler(CollectSomeData2_ListEvent);
               CollectSomeData2.BackEvent += new ICS.Display.Screen.ScreenEventHandler(CollectSomeData2_BackEvent);

               //Specify first screen
               Next(CollectSomeData1);
            }


            private void CollectSomeData1_EnterEvent(object sender, ScreenEventArgs e)
            {
               SomeTable1.Field1 = e.UserInput.ToString();

               if (SomeTable1.Fetch())
               {
                  //Do something with data
               }

               //Set next screen to show.
               Next(CollectSomeData2);
            }

            private void CollectSomeData2_BackEvent(object sender, ScreenEventArgs e)
            {
               Back(CollectSomeData1);
            }

            private void ApplicationExit_ExitEvent(object sender, ScreenEventArgs e)
            {
               Exit();
            }
